    if(transportTicks==8430){put("nativeParameterReadout",engine->playing.load()&&engine->observedPeak.load()>.001f&&engine->automationReadout[7][59].load()>=0&&engine->automationReadout[maxTracks][17].load()>=0);auto path=transportReport.getSiblingFile("native-parameter-automation.pulse");Project read;put("nativeParameterSave",saveProject(project,path).wasOk()&&loadProject(path,read).wasOk()&&read.clips.size()==3&&read.clips.back().automationTrack==-1);snapshot(transportReport.getSiblingFile("native-parameter-automation.png"));perform(stop);}
    if(transportTicks==8440){put("nativeParameterStop",engine->automationReadout[7][59].load()==-1&&engine->automationReadout[maxTracks][17].load()==-1);perform(undoAction);put("nativeParameterUndo",project.clips.size()==2&&project.clips.back().automationTarget==59);showAutomationParameters();put("nativeParameterMenu",Component::getNumCurrentlyModalComponents()>0);PopupMenu::dismissAllActiveMenus();}
    if(transportTicks==8450){perform(stop);project=emptyProject();project.songMode=true;project.loop=false;project.bpm=120;project.tracks[7].instrument=Instrument::analog;project.patterns[0].lanes[7]={{0,8,48,.8f}};Clip source;source.track=7;source.length=8;project.clips={source};selectedTrack=7;selectedClip=-1;editCursorBeat=0;publish();undoStack.clear();redoStack.clear();createParameterAutomation(0,7,revision);project.clips.back().points={{0,.2f},{8,.2f}};publish();automationWriteModeValue=1;put("nativeParameterWriteStart",beginAutomationWrite());engine->automationWrite.control(.8f,true);}
    if(transportTicks==8460){put("nativeParameterWriteTouchAudio",engine->playing.load()&&engine->observedPeak.load()>.001f&&std::abs(engine->automationReadout[7][0].load()-.8f)<1e-5);engine->automationWrite.control(.8f,false);}
    if(transportTicks==8470){put("nativeParameterWriteReturn",std::abs(engine->automationReadout[7][0].load()-.2f)<1e-5&&project.clips.size()==2);perform(stop);}
    if(transportTicks==8480){tickAutomationWrite();put("nativeParameterWriteReview",engine->automationWrite.result()&&automationWriteContext&&project.clips.size()==2);put("nativeParameterWriteApply",applyAutomationWrite()&&project.clips.size()==3&&undoStack.size()==2);snapshot(transportReport.getSiblingFile("native-automation-write.png"));}
    if(transportTicks==8490){perform(undoAction);bool undone=project.clips.size()==2;perform(redoAction);put("nativeParameterWriteHistory",undone&&project.clips.size()==3);selectedClip=1;automationWriteModeValue=2;put("nativeParameterWriteLatchStart",beginAutomationWrite());engine->automationWrite.control(.7f,true);}
    if(transportTicks==8500)engine->automationWrite.control(.7f,false);
    if(transportTicks==8510){put("nativeParameterWriteLatchAudio",engine->playing.load()&&std::abs(engine->automationReadout[7][0].load()-.7f)<1e-5);perform(stop);}
    if(transportTicks==8520){tickAutomationWrite();put("nativeParameterWriteLatchApply",applyAutomationWrite()&&project.clips.size()==4);auto path=transportReport.getSiblingFile("native-automation-write.pulse");Project reopened;put("nativeParameterWriteSave",saveProject(project,path).wasOk()&&loadProject(path,reopened).wasOk()&&reopened.clips.size()==4&&reopened.clips.back().points[0].hold);}
    if(transportTicks==8530){selectedClip=1;automationWriteModeValue=1;put("nativeParameterWriteInterruptStart",beginAutomationWrite());engine->automationWrite.control(.6f,true);}
    if(transportTicks==8540){signalDeviceInterruption();handleDeviceInterruption();}
    if(transportTicks==8550){handleDeviceInterruption();put("nativeParameterWriteDeviceDiscard",!automationWriteContext&&!engine->playing.load()&&project.clips.size()==4);automationWriteModeValue=0;perform(stop);}
