    if(transportTicks==8850){double at=engine->position.load();put("nativeParameterTrimReturn",std::abs(engine->automationReadout[7][0].load()-projectAutomationAt(project,0,7,at))<.005f);perform(stop);}
    if(transportTicks==8860){tickAutomationWrite();put("nativeParameterTrimApply",applyAutomationWrite()&&project.clips.size()==3&&project.clips.back().automationTrim&&project.clips[1].points[0].curve==AutomationCurve::smooth);snapshot(transportReport.getSiblingFile("native-trim.png"));auto file=transportReport.getSiblingFile("native-trim.pulse");Project read;put("nativeParameterTrimSave",saveProject(project,file).wasOk()&&loadProject(file,read).wasOk()&&read.clips.back().automationTrim);}
    if(transportTicks==8870){perform(undoAction);bool removed=project.clips.size()==2;perform(redoAction);put("nativeParameterTrimHistory",removed&&project.clips.size()==3&&project.clips.back().automationTrim);automationWriteModeValue=0;perform(stop);}

